import { HitObject, IHasComboInformation, IHasX, ControlPointInfo, BeatmapDifficultySection, ISpinnableObject, ISlidableObject, SliderPath, HitSample, EventGenerator, ModCombination, IMod, RulesetBeatmap, BeatmapConverter, IBeatmap, BeatmapProcessor, DifficultyAttributes, Autoplay, Cinema, DoubleTime, Easy, Flashlight, HalfTime, HardRock, Hidden, Nightcore, NoFail, NoMod, Perfect, Relax, SuddenDeath, PerformanceAttributes, DifficultyHitObject, IHitObject, StrainDecaySkill, DifficultyCalculator, Skill, PerformanceCalculator, IRuleset, IScoreInfo, ReplayFrame, IConvertibleReplayFrame, LegacyReplayFrame, ReplayConverter, IReplayFrame, Ruleset } from 'osu-classes';

/**
 * An osu!catch hit object.
 */
declare abstract class CatchHitObject extends HitObject implements IHasComboInformation, IHasX {
  /**
     * The radius of hit objects.
     */
  static OBJECT_RADIUS: number;
  currentComboIndex: number;
  comboIndex: number;
  comboIndexWithOffsets: number;
  comboOffset: number;
  lastInCombo: boolean;
  isNewCombo: boolean;
  timePreempt: number;
  scale: number;

  /**
     * X-offset of the hit object.
     */
  offsetX: number;
  private _originalX;

  /**
     * The starting X-position of the hit object.
     */
  get startX(): number;
  set startX(value: number);

  /**
     * The ending X-position of the hit object.
     */
  get endX(): number;

  /**
     * Original start X-position of the hit object before any changes.
     */
  get originalX(): number;

  /**
     * Start X-position with applied offset.
     */
  get effectiveX(): number;
  get randomSeed(): number;
  applyDefaultsToSelf(controlPoints: ControlPointInfo, difficulty: BeatmapDifficultySection): void;
  clone(): this;
}

declare abstract class PalpableHitObject extends CatchHitObject {
  hyperDashTarget: CatchHitObject | null;
  distanceToHyperDash: number;
  get hasHyperDash(): boolean;
  clone(): this;
}

declare class Banana extends PalpableHitObject {
  /**
     * The index of the current banana in the shower.
     */
  index: number;
  clone(): this;
}

declare class BananaShower extends CatchHitObject implements ISpinnableObject {
  /**
     * The time at which this hit object ends.
     */
  endTime: number;
  get duration(): number;
  set duration(value: number);
  createNestedHitObjects(): void;
  clone(): this;
}

declare class JuiceStream extends CatchHitObject implements ISlidableObject {
  static BASE_DISTANCE: number;
  tickDistance: number;
  velocity: number;
  legacyLastTickOffset?: number;
  path: SliderPath;
  nodeSamples: HitSample[][];
  repeats: number;
  get distance(): number;
  set distance(value: number);
  get spans(): number;
  get spanDuration(): number;
  get duration(): number;
  set duration(value: number);
  get endTime(): number;
  get endX(): number;
  applyDefaultsToSelf(controlPoints: ControlPointInfo, difficulty: BeatmapDifficultySection): void;
  createNestedHitObjects(): void;
  clone(): this;
}

